/**
 * The committed, content-addressed highlight artifact.
 *
 * One entry per `(surface, exact source bytes)` pair. The key is
 * `sha256(surface + "\0" + source)`; the entry carries the CLI's own
 * `sourceHash` (over the source alone) as a cross-check. No path, filename,
 * timestamp or colour is stored — only spans and their surface.
 *
 * The artifact is generated by `site/scripts/sync-highlight.mjs` and consumed
 * by both apps. Missing/invalid data is never guessed around: callers receive
 * `null` plus a reason and must render a plaintext fallback (the site gate then
 * fails).
 */

import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

export const HIGHLIGHT_ARTIFACT_FORMAT_VERSION = 1;

/** Find the repository root from any directory inside the checkout. */
export function findRepoRoot(start = process.cwd()) {
  let directory = start;
  for (let depth = 0; depth < 12; depth += 1) {
    if (existsSync(join(directory, 'crates')) && existsSync(join(directory, 'Cargo.toml'))) {
      return directory;
    }
    const parent = dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }
  return null;
}

/** The committed artifact's absolute path. */
export function artifactPath(root) {
  return join(root, 'site', 'data', 'highlighting', 'spans.json');
}

/** Lowercase hex SHA-256 of a UTF-8 string. */
export function sha256Hex(text) {
  return createHash('sha256').update(String(text), 'utf8').digest('hex');
}

/** The content-addressed key for one surface/source pair. */
export function keyFor(surface, source) {
  return sha256Hex(`${surface}\0${source}`);
}

const artifactCache = new Map();

/**
 * Load and validate the artifact once per path.
 *
 * Returns `{artifact, path, error}`. `artifact` is `null` when the file is
 * missing or invalid, and `error` explains why.
 */
export function loadArtifact(root = findRepoRoot()) {
  if (!root) return { artifact: null, path: null, error: 'cannot find the repository root' };
  const path = artifactPath(root);
  if (artifactCache.has(path)) return artifactCache.get(path);

  if (!existsSync(path)) {
    const result = { artifact: null, path, error: `missing ${path} — run node scripts/sync-highlight.mjs` };
    artifactCache.set(path, result);
    return result;
  }

  let parsed;
  try {
    parsed = JSON.parse(readFileSync(path, 'utf8'));
  } catch (error) {
    const result = { artifact: null, path, error: `invalid JSON at ${path}: ${error.message}` };
    artifactCache.set(path, result);
    return result;
  }

  if (!parsed || parsed.formatVersion !== HIGHLIGHT_ARTIFACT_FORMAT_VERSION) {
    const result = {
      artifact: null,
      path,
      error:
        `unsupported highlight artifact formatVersion ${parsed?.formatVersion ?? 'absent'} ` +
        `at ${path}; expected ${HIGHLIGHT_ARTIFACT_FORMAT_VERSION}`,
    };
    artifactCache.set(path, result);
    return result;
  }
  if (!parsed.entries || typeof parsed.entries !== 'object') {
    const result = { artifact: null, path, error: `highlight artifact at ${path} has no entries map` };
    artifactCache.set(path, result);
    return result;
  }

  const result = { artifact: parsed, path, error: null };
  artifactCache.set(path, result);
  return result;
}

/**
 * Look up one surface/source pair.
 *
 * Returns `{entry, error}`. A missing key is `{entry: null, error: null}`; a
 * present-but-inconsistent entry (surface or sourceHash mismatch) is
 * `{entry: null, error: "..."}` so the caller can report it instead of
 * silently rendering the wrong spans.
 */
export function lookupEntry(artifact, surface, source) {
  if (!artifact?.entries) return { entry: null, error: null };
  const key = keyFor(surface, source);
  const entry = artifact.entries[key];
  if (!entry) return { entry: null, error: null };

  if (entry.surface !== surface) {
    return { entry: null, error: `entry ${key} says surface ${entry.surface}, expected ${surface}` };
  }
  const sourceHash = `sha256:${sha256Hex(source)}`;
  if (entry.sourceHash !== sourceHash) {
    return {
      entry: null,
      error: `entry ${key} has sourceHash ${entry.sourceHash}, expected ${sourceHash}`,
    };
  }
  return { entry, error: null };
}

/** Test-only: clear the per-path cache. */
export function clearArtifactCache() {
  artifactCache.clear();
}
